def _seed_existing_businesses() -> None:
    """기존 사업장에 기본 단위·미분류 그룹·기본 창고를 넣고, 채권·채무 메뉴 분리를 반영한다."""
    conn = op.get_bind()
    business = sa.table("business", sa.column("id"), sa.column("menu_permissions", sa.JSON))
    unit = sa.table(
        "unit", *(sa.column(c) for c in
                  ("business_id", "name", "symbol", "kind", "base_ratio", "decimals", "sort_order", "is_active"))
    )
    group = sa.table(
        "item_group", *(sa.column(c) for c in
                        ("business_id", "code", "code_key", "name", "level", "sort_order", "is_active",
                         "is_uncategorized", "default_tax_exempt"))
    )
    warehouse = sa.table(
        "warehouse", *(sa.column(c) for c in ("business_id", "name", "is_default", "is_active"))
    )
    for biz_id, perms in conn.execute(sa.select(business.c.id, business.c.menu_permissions)).all():
        conn.execute(unit.insert(), [
            dict(business_id=biz_id, name=n, symbol=sym, kind=k, base_ratio=r, decimals=d,
                 sort_order=i, is_active=True)
            for i, (n, sym, k, r, d) in enumerate(_UNITS)
        ])
        conn.execute(group.insert().values(
            business_id=biz_id, code="UNCAT", code_key="UNCAT", name="미분류", level=1,
            sort_order=9999, is_active=True, is_uncategorized=True, default_tax_exempt=False,
        ))
        conn.execute(warehouse.insert().values(
            business_id=biz_id, name="기본 창고", is_default=True, is_active=True
        ))
        if perms:
            new = {}
            for role, menus in perms.items():
                menus = [m for m in menus if m != "ledger"]
                if "ledger" in perms[role]:
                    menus += ["receivables", "payables"]
                new[role] = menus
            conn.execute(
                business.update().where(business.c.id == biz_id).values(menu_permissions=new)
            )

